export const STORAGE_KEY='hitoami.v1';
export function initialState(){return {version:1,favorites:[],progress:{},dimensions:{},customProjects:[],videoOverrides:{}};}
export function loadState(storage){try{const s=JSON.parse(storage.getItem(STORAGE_KEY));if(s?.version!==1)return initialState();return {version:1,favorites:Array.isArray(s.favorites)?s.favorites.filter(x=>typeof x==='string'):[],progress:s.progress&&typeof s.progress==='object'&&!Array.isArray(s.progress)?s.progress:{},dimensions:s.dimensions&&typeof s.dimensions==='object'?s.dimensions:{},customProjects:Array.isArray(s.customProjects)?s.customProjects.filter(p=>p&&typeof p.id==='string'&&typeof p.name==='string'&&Array.isArray(p.steps)&&Array.isArray(p.materials)&&Array.isArray(p.techniques)&&Array.isArray(p.categories)):[],videoOverrides:s.videoOverrides&&typeof s.videoOverrides==='object'?s.videoOverrides:{}};}catch{return initialState();}}
export function saveState(storage,state){storage.setItem(STORAGE_KEY,JSON.stringify(state));}
export function completedSteps(state,project){const done=state.progress[project.id];return project.steps.filter(s=>Array.isArray(done)&&done.includes(s.id)).map(s=>s.id);}
export function nextStep(state,project){const done=completedSteps(state,project);return Math.max(0,project.steps.findIndex(s=>!done.includes(s.id)));}
export function setStep(state,project,stepId,done){if(!project.steps.some(s=>s.id===stepId))throw new Error('工程が見つかりません。');const ids=new Set(completedSteps(state,project));done?ids.add(stepId):ids.delete(stepId);state.progress[project.id]=[...ids];}
export function dimensionGuide(dimensions){const {width,diameter,height}=dimensions;const span=diameter?Math.round(diameter*Math.PI*10)/10:width;return `${diameter?'円周':'幅'}は約${span||'—'}cm${height?`、仕上がり高さは${height}cm`:''}が目安です。伸ばさずに置いた試し編みで幅を確認しましょう。正確な目数にはゲージと模様の繰り返し数が必要です。`;}
export function validVideoURL(raw){try{const url=new URL(raw);if(url.protocol!=='https:'||url.username||url.password)return false;return ['youtube.com','www.youtube.com','m.youtube.com','youtu.be','clover.co.jp','www.clover.co.jp'].includes(url.hostname);}catch{return false;}}
